@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Space+Mono:wght@400;700&display=swap');
:root{--ink:#071012;--panel:#0b1719;--line:#294447;--mint:#9ef5d0;--acid:#d6ff71;--muted:#89a6a4;--red:#ff665e;--mono:'Space Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050a0c;color:#e8f4ec;font-family:var(--mono)}body{user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:420px;overflow:hidden;background:#081114}#game{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:2;opacity:.13;background:repeating-linear-gradient(0deg,transparent 0px,transparent 2px,rgba(0,0,0,.4) 3px);mix-blend-mode:multiply}.game-shell:after{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at center,transparent 48%,rgba(0,5,7,.38) 100%);box-shadow:inset 0 0 0 1px rgba(139,255,207,.12)}
.topbar{height:64px;position:absolute;z-index:5;left:0;right:0;top:0;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(180,245,219,.1);background:linear-gradient(180deg,rgba(4,12,14,.86),rgba(4,12,14,.24));font-size:10px;letter-spacing:.13em}.brand{display:flex;align-items:center;gap:11px;font-weight:bold;color:#d4ede2;letter-spacing:.17em}.brand-mark{font-size:16px;color:var(--acid);transform:scaleX(1.3)}.brand-dim{color:#64817c;margin:0 2px}.mission{display:flex;align-items:center;gap:11px;color:#b9d1c9}.live-dot{height:6px;width:6px;background:var(--acid);box-shadow:0 0 10px var(--acid);border-radius:50%}.mission-divider{color:#57716c}.mission #missionState{color:var(--acid)}.sound-button{border:0;background:none;color:#b6cdc5;font:10px var(--mono);letter-spacing:.1em;cursor:pointer}.sound-button span{font-size:9px;color:#718d86;margin-left:5px}.sound-button.muted{color:#74817b}
.hud{position:absolute;z-index:4;bottom:48px;left:4.1%;right:4.1%;height:76px;display:grid;grid-template-columns:1fr 1fr 1fr;align-items:end;pointer-events:none;text-shadow:0 2px 6px #000}.hud-left{width:205px}.stat-label,.weapon-name,.wave-label{font-size:9px;letter-spacing:.14em;color:#acc5bd}.health-row{display:flex;gap:8px;align-items:center;margin-top:7px}.health-icon{font-size:14px;color:var(--acid)}.health-track,.armor-track{height:8px;background:#1a3030;border:1px solid #41605a;flex:1;transform:skewX(-11deg)}.health-fill,.armor-fill{height:100%;background:var(--acid);box-shadow:0 0 8px rgba(214,255,113,.38);transition:width .15s}.health-row b{width:24px;color:#e9fff0;font-size:12px}.armor-row{display:flex;align-items:center;gap:7px;margin:5px 0 0 23px;font-size:8px;color:#789790;letter-spacing:.1em}.armor-track{height:4px;border:0}.armor-fill{background:#75c8e3;box-shadow:none}.armor-row b{font-size:9px;font-weight:400;color:#9ccad1;width:15px}.hud-center{text-align:center;align-self:center;padding-top:18px}.wave-label{color:#b4cfbf}.wave-label b{color:var(--acid);font-size:14px;margin-left:5px}.enemies-left{display:flex;align-items:center;justify-content:center;gap:6px;margin-top:5px;font-size:8px;letter-spacing:.15em;color:#90aaa2}.enemies-left b{font-size:12px;color:#eff8ed}.enemy-dot{font-size:8px;color:var(--red)}.hud-right{text-align:right}.weapon-name{color:#cbdfd4;font-size:10px}.weapon-icon{color:var(--acid);font-size:13px;margin-right:4px}.weapon-tag{color:#718a82;border-left:1px solid #38514a;margin-left:6px;padding-left:7px;font-size:9px}.ammo-row{display:flex;justify-content:flex-end;align-items:baseline;gap:6px;margin-top:0}.ammo-row>b{font:800 40px/.95 var(--display);color:#f3fff2;letter-spacing:.01em}.ammo-divider{color:#7b9690;font-size:17px}.ammo-row>span:nth-of-type(2){font:500 19px var(--display);color:#a7c2b9}.ammo-caption{font:9px var(--mono)!important;letter-spacing:.14em;color:#8aa39b!important;margin-left:5px}.reload-note{font-size:8px;letter-spacing:.08em;color:#6b8880;margin-top:5px}.reload-note.active{color:var(--acid);animation:pulse .5s infinite alternate}@keyframes pulse{to{opacity:.45}}
.crosshair{position:absolute;z-index:4;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none}.crosshair i{position:absolute;background:rgba(222,255,231,.85);box-shadow:0 0 3px #14281e}.crosshair i:nth-child(1){width:2px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:2px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){width:5px;height:2px;left:0;top:8px}.crosshair i:nth-child(4){width:5px;height:2px;right:0;top:8px}.crosshair b{position:absolute;width:2px;height:2px;left:8px;top:8px;background:var(--acid)}.crosshair.hit i,.crosshair.hit b{background:#ff7166}.hit-marker{z-index:4;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font:20px var(--mono);color:#fff3bf;text-shadow:0 0 7px #ffae58;opacity:0;pointer-events:none}.hit-marker.show{opacity:1}.damage-flash{position:absolute;z-index:3;inset:0;pointer-events:none;background:radial-gradient(ellipse,transparent 35%,rgba(255,35,47,.42));opacity:0;transition:opacity .08s}.damage-flash.show{opacity:1}.bottom-left,.bottom-right{position:absolute;z-index:4;bottom:22px;font-size:8px;letter-spacing:.1em;color:#8ba39b;text-shadow:0 1px 5px #000}.bottom-left{left:4.1%}.bottom-right{right:4.1%}.keycap{display:inline-block;padding:3px 5px;border:1px solid rgba(161,202,183,.27);background:rgba(4,14,15,.55);color:#cee5d7;font-size:8px;margin-right:3px}.bottom-sep{color:#48635a;margin:0 7px}
.overlay,.end-overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:rgba(4,12,14,.58);backdrop-filter:blur(2px)}.overlay-grid{position:absolute;inset:0;opacity:.09;background-image:linear-gradient(rgba(139,233,193,.25) 1px,transparent 1px),linear-gradient(90deg,rgba(139,233,193,.25) 1px,transparent 1px);background-size:42px 42px;mask-image:radial-gradient(ellipse,black,transparent 75%)}.menu-card{position:relative;width:min(510px,90vw);text-align:center;padding:22px 36px 16px;background:linear-gradient(145deg,rgba(10,25,26,.95),rgba(7,16,18,.89));border:1px solid rgba(150,221,186,.25);box-shadow:0 22px 80px #020708,0 0 0 5px rgba(124,197,158,.025);clip-path:polygon(0 0,calc(100% - 17px) 0,100% 17px,100% 100%,0 100%);}.menu-card:before,.end-card:before{content:"";position:absolute;left:0;top:0;width:76px;height:2px;background:var(--acid);box-shadow:0 0 12px rgba(214,255,113,.55)}.eyebrow{display:flex;align-items:center;justify-content:center;gap:10px;color:#9bb8a9;font-size:8px;letter-spacing:.27em}.eyebrow-line{width:32px;height:1px;background:#567166}.title-wrap{position:relative;display:inline-block;margin:10px 0 0}.title-wrap h1{margin:0;color:#e9f4e9;font:900 clamp(54px,8vw,82px)/.87 var(--display);letter-spacing:-.02em;text-shadow:4px 4px 0 #152c29}.title-wrap h1 span{display:block;color:var(--acid);font-size:.77em;letter-spacing:.22em;padding-left:.2em;text-shadow:3px 3px 0 #28402c}.title-stamp{position:absolute;top:2px;right:-42px;font:700 12px var(--mono);color:#0a1512;background:var(--acid);padding:4px 6px;transform:rotate(6deg);box-shadow:2px 2px 0 #36503a}.subtitle{font-size:9px;letter-spacing:.28em;color:#8da69c;margin:14px 0 15px}.menu-divider{display:flex;align-items:center;gap:10px;width:68%;margin:0 auto 13px;color:var(--acid);font-size:8px}.menu-divider span{height:1px;background:#29433b;flex:1}.briefing{font:11px/1.8 var(--mono);color:#b4c7bc;margin:0 0 17px}.start-button{display:flex;align-items:center;justify-content:space-between;width:226px;margin:0 auto;border:1px solid #d3ff76;background:var(--acid);color:#0a1911;padding:13px 15px;font:700 11px var(--mono);letter-spacing:.15em;cursor:pointer;box-shadow:4px 4px 0 #33503b;transition:transform .12s,box-shadow .12s,background .12s}.start-button b{font-size:17px;font-weight:400}.start-button:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 #33503b;background:#e1ff95}.controls{display:flex;justify-content:center;gap:17px;margin:21px 0 18px}.controls>div{display:flex;align-items:center;gap:3px}.controls kbd{display:inline-grid;place-items:center;min-width:19px;height:20px;border:1px solid #344d45;background:#111f1c;color:#d2e6d6;font:9px var(--mono);padding:0 3px}.controls span{font-size:7px;color:#7e9c90;letter-spacing:.09em;margin-left:4px}.menu-foot{display:flex;justify-content:space-between;border-top:1px solid #263d36;padding-top:10px;color:#607b70;font-size:7px;letter-spacing:.12em}.corner-note{position:absolute;right:4.1%;top:90px;color:#748e84;font-size:8px;line-height:1.9;letter-spacing:.12em;text-align:right}.version{position:absolute;left:4.1%;bottom:23px;color:#799189;font-size:8px;letter-spacing:.08em}.version span{color:var(--acid);font-size:6px;margin:0 5px}.end-overlay{background:rgba(4,12,14,.72)}.end-overlay.hidden{display:none}.end-card{position:relative;width:min(430px,90vw);padding:35px;text-align:center;background:#0a1919;border:1px solid #38534b;box-shadow:0 20px 70px #000}.end-card .eyebrow{color:var(--acid)}.end-card h2{font:800 36px var(--display);margin:14px 0 3px}.end-card p{color:#9ab1a5;font-size:11px}.final-score{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #2a433b;border-bottom:1px solid #2a433b;padding:12px 0;margin:20px 0;color:#819b8e;font-size:9px;letter-spacing:.15em}.final-score b{font:700 24px var(--display);color:var(--acid)}
.mobile-controls{display:none;position:absolute;z-index:5;inset:auto 0 10px;pointer-events:none}.joystick{position:absolute;left:22px;bottom:20px;width:108px;height:108px;border:1px solid rgba(203,255,215,.3);border-radius:50%;background:rgba(7,19,18,.38);pointer-events:auto;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;width:42px;height:42px;border-radius:50%;transform:translate(-50%,-50%);background:rgba(180,229,190,.48);border:1px solid rgba(229,255,225,.6)}.mobile-fire,.mobile-reload{pointer-events:auto;position:absolute;right:25px;bottom:25px;width:75px;height:75px;border-radius:50%;border:1px solid rgba(214,255,113,.65);background:rgba(31,56,36,.65);color:#e1ff94;font:700 10px var(--mono);touch-action:none}.mobile-reload{right:115px;bottom:21px;width:49px;height:49px;border-color:#78998a;background:rgba(12,31,29,.7);color:#d8e9dc}
@media(max-width:700px){.topbar{height:48px;padding:0 15px}.mission{font-size:8px;gap:6px}.brand{font-size:9px;gap:6px}.sound-button span{display:none}.hud{bottom:152px;left:15px;right:15px;grid-template-columns:1fr 1fr 1fr;height:57px}.hud-left{width:auto}.stat-label{font-size:7px}.health-row{gap:4px}.health-icon{font-size:11px}.health-track{height:6px}.health-row b{font-size:10px;width:20px}.armor-row{margin-left:14px;font-size:7px;gap:4px}.hud-center{padding-top:13px}.wave-label{font-size:7px}.enemies-left{font-size:7px}.hud-right .weapon-name{font-size:7px}.weapon-tag{font-size:7px;margin-left:3px;padding-left:4px}.ammo-row>b{font-size:31px}.ammo-row>span:nth-of-type(2){font-size:15px}.ammo-caption{display:none}.reload-note{font-size:6px}.bottom-left,.bottom-right{display:none}.mobile-controls{display:block}.crosshair{width:14px;height:14px}.crosshair i:nth-child(1){left:6px}.crosshair i:nth-child(2){left:6px}.crosshair i:nth-child(3){top:6px}.crosshair i:nth-child(4){top:6px}.crosshair b{left:6px;top:6px}.menu-card{padding:18px 17px 13px}.title-wrap h1{font-size:61px}.briefing{font-size:10px}.controls{gap:8px;margin:16px 0}.controls span{font-size:6px}.controls kbd{min-width:16px;height:18px}.corner-note{top:60px;right:15px;font-size:7px}.version{left:15px;bottom:12px;font-size:6px}.menu-foot{font-size:6px}.subtitle{font-size:8px}.start-button{width:210px;padding:11px 13px}.end-card{padding:28px 20px}}
@media(max-height:600px) and (min-width:701px){.menu-card{transform:scale(.82)}.hud{bottom:35px}.topbar{height:50px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const W = 480, H = 270, FOV = Math.PI / 3;
  canvas.width = W; canvas.height = H;
  ctx.imageSmoothingEnabled = false;

  const map = [
    '################',
    '#......#.......#',
    '#.##...#..##...#',
    '#......#.......#',
    '#..............#',
    '#..##......##..#',
    '#..#..........##',
    '#..#..##.......#',
    '#.....##.......#',
    '##............##',
    '#......##......#',
    '#..............#',
    '#..##......##..#',
    '#..............#',
    '#..............#',
    '################'
  ];
  const $ = id => document.getElementById(id);
  const ui = { start: $('startOverlay'), end: $('endOverlay'), hud: $('hud'), mission: $('missionState'), health: $('healthFill'), healthText: $('healthText'), armor: $('armorFill'), armorText: $('armorText'), ammo: $('ammoText'), reserve: $('reserveText'), wave: $('waveText'), enemies: $('enemyText'), score: $('finalScore'), endTitle: $('endTitle'), endCopy: $('endCopy'), reload: $('reloadNote'), crosshair: $('crosshair'), hit: $('hitMarker'), flash: $('damageFlash'), mobile: $('mobileControls'), joy: $('joystick'), knob: $('joyKnob') };
  const player = { x: 2.5, y: 2.5, angle: .15, health: 100, armor: 50, ammo: 24, reserve: 120, score: 0, wave: 0, kills: 0, bob: 0, hurt: 0, recoil: 0, muzzle: 0, reloading: 0, fireCooldown: 0, alive: true };
  let enemies = [], particles = [], running = false, started = false, last = performance.now(), animTime = 0;
  let keys = Object.create(null), pointerLocked = false, fireHeld = false, soundOn = true, audio = null;
  let joyActive = false, joyOrigin = null, joyVector = { x: 0, y: 0 }, lastTouchX = null;
  const depthBuffer = new Float32Array(W);
  const random = (min, max) => min + Math.random() * (max - min);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const normAngle = a => { while (a > Math.PI) a -= Math.PI * 2; while (a < -Math.PI) a += Math.PI * 2; return a; };
  function isWall(x, y) { const mx = Math.floor(x), my = Math.floor(y); return !map[my] || map[my][mx] !== '.'; }
  function tone(freq, duration, type = 'square', volume = .035) {
    if (!soundOn) return;
    try { audio ||= new (window.AudioContext || window.webkitAudioContext)(); const o = audio.createOscillator(), g = audio.createGain(); o.type = type; o.frequency.setValueAtTime(freq, audio.currentTime); o.frequency.exponentialRampToValueAtTime(Math.max(45, freq * .38), audio.currentTime + duration); g.gain.setValueAtTime(volume, audio.currentTime); g.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration); o.connect(g); g.connect(audio.destination); o.start(); o.stop(audio.currentTime + duration); } catch (_) {}
  }
  function spawnWave() {
    player.wave++;
    const count = 3 + player.wave * 2;
    for (let i = 0; i < count; i++) {
      let x, y, tries = 0;
      do { x = random(3, 13); y = random(2, 13); tries++; } while ((isWall(x, y) || Math.hypot(x - player.x, y - player.y) < 4 || enemies.some(e => Math.hypot(e.x - x, e.y - y) < 1.4)) && tries < 150);
      if (tries < 150) enemies.push({ x, y, hp: player.wave >= 3 && i % 4 === 0 ? 3 : 2, maxHp: player.wave >= 3 && i % 4 === 0 ? 3 : 2, speed: random(.52, .78) + player.wave * .035, attack: random(.6, 1.4), phase: random(0, 6), hit: 0, type: i % 4 === 0 ? 'heavy' : 'scout', dead: false });
    }
    updateHud();
  }
  function startGame() {
    if (started && running) return;
    started = true; running = true; player.alive = true;
    Object.assign(player, { x: 2.5, y: 2.5, angle: .15, health: 100, armor: 50, ammo: 24, reserve: 120, score: 0, wave: 0, kills: 0, reloading: 0, fireCooldown: 0 });
    enemies = []; particles = []; ui.start.classList.add('hidden'); ui.end.classList.add('hidden'); ui.mission.textContent = 'TEMİZLE';
    if (canvas.requestPointerLock && window.innerWidth > 700) canvas.requestPointerLock();
    spawnWave(); updateHud();
  }
  function finishGame(win) {
    running = false; player.alive = false;
    if (document.pointerLockElement) document.exitPointerLock();
    ui.endTitle.textContent = win ? 'GÖREV TAMAMLANDI' : 'SİNYAL KESİLDİ';
    ui.endCopy.textContent = win ? 'Sektör temizlendi. Şimdilik.' : `Dalga ${String(player.wave).padStart(2, '0')}’de düştün. Makineler hâlâ geliyor.`;
    ui.score.textContent = String(player.score).padStart(4, '0'); ui.end.classList.remove('hidden'); ui.mission.textContent = win ? 'TAMAMLANDI' : 'BAĞLANTI KOPTU';
  }
  function updateHud() {
    ui.health.style.width = `${player.health}%`; ui.healthText.textContent = player.health;
    ui.armor.style.width = `${player.armor * 2}%`; ui.armorText.textContent = player.armor;
    ui.ammo.textContent = player.ammo; ui.reserve.textContent = player.reserve;
    ui.wave.textContent = String(player.wave).padStart(2, '0');
    ui.enemies.textContent = enemies.filter(e => !e.dead).length;
  }
  function reload() {
    if (!running || player.reloading || player.ammo >= 24 || player.reserve <= 0) return;
    player.reloading = 1.2; ui.reload.textContent = 'ŞARJÖR DEĞİŞTİRİLİYOR'; ui.reload.classList.add('active'); tone(240, .08, 'triangle', .025);
  }
  function shoot() {
    if (!running || player.reloading || player.fireCooldown > 0) return;
    if (player.ammo <= 0) { tone(100, .05, 'square', .018); reload(); return; }
    player.ammo--; player.fireCooldown = .19; player.recoil = 1; player.muzzle = .085; tone(115, .085, 'sawtooth', .045); tone(290, .045, 'square', .018);
    let target = null, nearest = 1.25;
    for (const e of enemies) {
      if (e.dead) continue;
      const dx = e.x - player.x, dy = e.y - player.y, dist = Math.hypot(dx, dy), a = Math.abs(normAngle(Math.atan2(dy, dx) - player.angle));
      if (a < .13 + .018 / dist && dist < nearest && hasLine(player.x, player.y, e.x, e.y)) { nearest = dist; target = e; }
    }
    if (target) {
      target.hp--; target.hit = .12; player.score += 10; ui.crosshair.classList.add('hit'); ui.hit.classList.add('show'); setTimeout(() => { ui.crosshair.classList.remove('hit'); ui.hit.classList.remove('show'); }, 100);
      for (let i = 0; i < 7; i++) particles.push({ x: target.x, y: target.y, z: random(.35, 1.7), life: random(.12, .32), color: i % 2 ? '#f5e681' : '#ff7664', vx: random(-1, 1), vy: random(-1, 1) });
      if (target.hp <= 0) { target.dead = true; player.kills++; player.score += target.type === 'heavy' ? 100 : 75; tone(480, .12, 'triangle', .035); }
    }
    if (player.ammo === 0 && player.reserve > 0) setTimeout(reload, 240);
    updateHud();
  }
  function hasLine(x1, y1, x2, y2) {
    const d = Math.hypot(x2 - x1, y2 - y1), steps = Math.ceil(d * 10);
    for (let i = 1; i < steps; i++) { const t = i / steps; if (isWall(x1 + (x2 - x1) * t, y1 + (y2 - y1) * t)) return false; }
    return true;
  }
  function takeDamage(amount) {
    const absorbed = Math.min(player.armor, Math.ceil(amount * .65)); player.armor -= absorbed; player.health = Math.max(0, player.health - (amount - absorbed));
    player.hurt = .26; ui.flash.classList.add('show'); setTimeout(() => ui.flash.classList.remove('show'), 130); tone(85, .13, 'sawtooth', .04); updateHud();
    if (player.health <= 0) finishGame(false);
  }
  function update(dt) {
    animTime += dt; player.fireCooldown = Math.max(0, player.fireCooldown - dt); player.muzzle = Math.max(0, player.muzzle - dt); player.recoil = Math.max(0, player.recoil - dt * 5); player.hurt = Math.max(0, player.hurt - dt);
    if (!running) return;
    if (player.reloading > 0) { player.reloading -= dt; if (player.reloading <= 0) { const n = Math.min(24 - player.ammo, player.reserve); player.ammo += n; player.reserve -= n; ui.reload.textContent = 'R — ŞARJÖR DEĞİŞTİR'; ui.reload.classList.remove('active'); tone(350, .07, 'triangle', .025); updateHud(); } }
    if (fireHeld || keys.Space) shoot();
    const f = (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0) + (-joyVector.y);
    const s = (keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0) + joyVector.x;
    const turn = (keys.ArrowRight ? 1 : 0) - (keys.ArrowLeft ? 1 : 0);
    player.angle += turn * dt * 2.2;
    const speed = (keys.ShiftLeft ? 3.8 : 2.65) * dt;
    const mx = (Math.cos(player.angle) * f - Math.sin(player.angle) * s) * speed;
    const my = (Math.sin(player.angle) * f + Math.cos(player.angle) * s) * speed;
    if (Math.abs(f) + Math.abs(s) > .05) player.bob += dt * 11;
    const radius = .2;
    if (!isWall(player.x + mx + Math.sign(mx) * radius, player.y)) player.x += mx;
    if (!isWall(player.x, player.y + my + Math.sign(my) * radius)) player.y += my;
    for (const e of enemies) {
      if (e.dead) continue;
      e.hit = Math.max(0, e.hit - dt);
      const dx = player.x - e.x, dy = player.y - e.y, dist = Math.hypot(dx, dy);
      e.phase += dt * 4;
      if (dist > .72) { const step = e.speed * dt, vx = dx / dist * step, vy = dy / dist * step; if (!isWall(e.x + vx, e.y)) e.x += vx; if (!isWall(e.x, e.y + vy)) e.y += vy; }
      e.attack -= dt;
      if (dist < 1.18 && e.attack <= 0) { takeDamage(e.type === 'heavy' ? 13 : 9); e.attack = random(1.05, 1.6); }
    }
    particles = particles.filter(p => (p.life -= dt) > 0);
    if (enemies.length && enemies.every(e => e.dead)) { if (player.wave >= 5) { finishGame(true); return; } enemies = []; player.reserve = Math.min(240, player.reserve + 18); player.health = Math.min(100, player.health + 12); player.armor = Math.min(50, player.armor + 8); spawnWave(); }
    updateHud();
  }
  function castRay(angle) {
    const rayX = Math.cos(angle), rayY = Math.sin(angle), mapX0 = Math.floor(player.x), mapY0 = Math.floor(player.y);
    const deltaX = Math.abs(1 / (rayX || 1e-8)), deltaY = Math.abs(1 / (rayY || 1e-8));
    let stepX, stepY, sideX, sideY, mapX = mapX0, mapY = mapY0;
    if (rayX < 0) { stepX = -1; sideX = (player.x - mapX) * deltaX; } else { stepX = 1; sideX = (mapX + 1 - player.x) * deltaX; }
    if (rayY < 0) { stepY = -1; sideY = (player.y - mapY) * deltaY; } else { stepY = 1; sideY = (mapY + 1 - player.y) * deltaY; }
    let side = 0, count = 0;
    while (count++ < 28) { if (sideX < sideY) { sideX += deltaX; mapX += stepX; side = 0; } else { sideY += deltaY; mapY += stepY; side = 1; } if (!map[mapY] || map[mapY][mapX] !== '.') break; }
    const dist = Math.max(.001, side === 0 ? sideX - deltaX : sideY - deltaY);
    let wallX = side === 0 ? player.y + dist * rayY : player.x + dist * rayX; wallX -= Math.floor(wallX);
    return { dist, side, wallX, mapX, mapY };
  }
  function drawWorld() {
    const sky = ctx.createLinearGradient(0, 0, 0, H * .54); sky.addColorStop(0, '#101e26'); sky.addColorStop(.72, '#1e3434'); sky.addColorStop(1, '#718064'); ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H / 2);
    const floor = ctx.createLinearGradient(0, H / 2, 0, H); floor.addColorStop(0, '#283d35'); floor.addColorStop(.28, '#152822'); floor.addColorStop(1, '#080f12'); ctx.fillStyle = floor; ctx.fillRect(0, H / 2, W, H / 2);
    ctx.fillStyle = 'rgba(177,235,174,.22)'; ctx.fillRect(0, H / 2 - 1, W, 2);
    // Perspective floor seams
    for (let y = H / 2 + 11; y < H; y += 14) { ctx.fillStyle = `rgba(129,185,143,${.08 * (y / H)})`; ctx.fillRect(0, y, W, 1); }
    for (let x = -W; x < W * 2; x += 38) { ctx.strokeStyle = 'rgba(105,166,130,.12)'; ctx.beginPath(); ctx.moveTo(W / 2, H / 2); ctx.lineTo(x, H); ctx.stroke(); }
    for (let x = 0; x < W; x += 2) {
      const angle = player.angle + Math.atan((2 * x / W - 1) * Math.tan(FOV / 2));
      const hit = castRay(angle), dist = hit.dist * Math.cos(angle - player.angle); depthBuffer[x] = dist;
      const wallH = Math.min(H * 2, H / dist), top = Math.floor((H - wallH) / 2), bottom = Math.floor(top + wallH);
      let tex = Math.floor(hit.wallX * 8); if (hit.side === 0) tex = 7 - tex;
      const shade = clamp(1 - dist * .085, .2, .92) * (hit.side ? .72 : 1);
      const stripe = tex === 0 || tex === 7;
      const r = Math.floor((stripe ? 87 : 45) * shade), g = Math.floor((stripe ? 154 : 108) * shade), b = Math.floor((stripe ? 125 : 91) * shade);
      ctx.fillStyle = `rgb(${r},${g},${b})`; ctx.fillRect(x, top, 2, wallH);
      // modular wall panels
      const panelTop = top + wallH * .15, panelH = wallH * .68;
      if (tex === 2 || tex === 3 || tex === 5) { ctx.fillStyle = `rgba(8,21,22,${.3 * shade})`; ctx.fillRect(x, panelTop, 2, panelH); }
      if (tex === 0 || tex === 7) { ctx.fillStyle = `rgba(178,255,162,${.38 * shade})`; ctx.fillRect(x, top + wallH * .22, 2, Math.max(1, wallH * .028)); }
      const grout = top + wallH * .51; ctx.fillStyle = `rgba(3,11,13,${.27 * shade})`; ctx.fillRect(x, grout, 2, Math.max(1, wallH * .012));
      if (dist < 5 && (hit.mapX + hit.mapY) % 4 === 0 && tex === 4) { ctx.fillStyle = `rgba(178,232,174,${.22 * shade})`; ctx.fillRect(x, top + wallH * .3, 2, Math.max(1, wallH * .08)); }
    }
    drawSprites(); drawWeapon(); drawReticle();
  }
  function drawSprites() {
    const sprites = enemies.filter(e => !e.dead).map(e => ({ e, dist: Math.hypot(e.x - player.x, e.y - player.y) })).sort((a, b) => b.dist - a.dist);
    for (const { e, dist } of sprites) {
      const angle = normAngle(Math.atan2(e.y - player.y, e.x - player.x) - player.angle);
      if (Math.abs(angle) > FOV * .72 || dist < .3) continue;
      const sx = W / 2 + Math.tan(angle) / Math.tan(FOV / 2) * W / 2;
      const size = clamp(H / dist * (e.type === 'heavy' ? 1.03 : .83), 5, H * 1.65);
      if (sx < -size || sx > W + size || dist > depthBuffer[clamp(Math.round(sx), 0, W - 1)] + .25) continue;
      const floorY = H / 2 + size * .5, top = floorY - size;
      const x = Math.round(sx), w = Math.round(size * .58), center = x;
      ctx.fillStyle = `rgba(0,0,0,${clamp(.42 - dist * .025, .08, .3)})`; ctx.fillRect(center - w * .62, floorY - 2, w * 1.25, Math.max(2, size * .11));
      const glow = e.hit ? '#fff7b5' : e.type === 'heavy' ? '#e37a55' : '#63efc3';
      // antenna + head
      ctx.fillStyle = '#172727'; ctx.fillRect(center - w * .23, top + size * .08, w * .46, size * .23);
      ctx.fillStyle = glow; ctx.fillRect(center - w * .18, top + size * .17, w * .36, Math.max(2, size * .04));
      ctx.fillStyle = '#0c171a'; ctx.fillRect(center - w * .31, top + size * .30, w * .62, size * .40);
      ctx.fillStyle = e.hit ? '#e9ffd0' : e.type === 'heavy' ? '#9a5142' : '#277d6b'; ctx.fillRect(center - w * .39, top + size * .32, w * .78, size * .34);
      ctx.fillStyle = '#162525'; ctx.fillRect(center - w * .26, top + size * .37, w * .52, size * .11);
      ctx.fillStyle = glow; ctx.fillRect(center - w * .18, top + size * .40, w * .36, Math.max(2, size * .035));
      // torso detail
      ctx.fillStyle = '#162426'; ctx.fillRect(center - w * .18, top + size * .49, w * .36, size * .12);
      ctx.fillStyle = '#8ea68a'; ctx.fillRect(center - w * .05, top + size * .51, w * .1, size * .06);
      ctx.fillStyle = '#1b2929'; ctx.fillRect(center - w * .52, top + size * .42, w * .16, size * .20); ctx.fillRect(center + w * .36, top + size * .42, w * .16, size * .20);
      ctx.fillStyle = '#1b2526'; ctx.fillRect(center - w * .29, top + size * .70, w * .22, size * .22); ctx.fillRect(center + w * .07, top + size * .70, w * .22, size * .22);
      ctx.fillStyle = '#78c59b'; ctx.fillRect(center - w * .24, floorY - size * .06, w * .12, Math.max(2, size * .04)); ctx.fillRect(center + w * .12, floorY - size * .06, w * .12, Math.max(2, size * .04));
      if (e.hp < e.maxHp) { ctx.fillStyle = '#14221f'; ctx.fillRect(center - w * .5, top - 5, w, 2); ctx.fillStyle = '#e5c76d'; ctx.fillRect(center - w * .5, top - 5, w * e.hp / e.maxHp, 2); }
    }
    for (const p of particles) { const angle = normAngle(Math.atan2(p.y - player.y, p.x - player.x) - player.angle); if (Math.abs(angle) > FOV / 2) continue; const sx = W / 2 + Math.tan(angle) / Math.tan(FOV / 2) * W / 2, size = Math.max(1, H / Math.hypot(p.x - player.x, p.y - player.y) * .025); ctx.fillStyle = p.color; ctx.fillRect(sx + p.vx * p.life * 8, H / 2 - p.z * 16, size, size); }
  }
  function drawWeapon() {
    const bob = Math.sin(player.bob) * 2, kick = player.recoil * 11, x = W / 2 + 38, y = H - 11 + bob + kick;
    ctx.fillStyle = 'rgba(0,0,0,.4)'; ctx.fillRect(x - 70, y - 53, 144, 60);
    // gauntlet
    ctx.fillStyle = '#633f35'; ctx.fillRect(x - 56, y - 38, 35, 54); ctx.fillRect(x + 32, y - 43, 35, 60);
    ctx.fillStyle = '#c18763'; ctx.fillRect(x - 54, y - 29, 33, 39); ctx.fillRect(x + 34, y - 35, 32, 45);
    ctx.fillStyle = '#e0ad7b'; ctx.fillRect(x - 49, y - 27, 24, 8); ctx.fillRect(x + 37, y - 31, 24, 7);
    // rifle stock and body
    ctx.fillStyle = '#10191d'; ctx.fillRect(x - 36, y - 70, 72, 81);
    ctx.fillStyle = '#26363a'; ctx.fillRect(x - 30, y - 82, 60, 53); ctx.fillRect(x - 24, y - 95, 48, 21);
    ctx.fillStyle = '#526461'; ctx.fillRect(x - 23, y - 91, 46, 7); ctx.fillRect(x - 27, y - 72, 54, 6);
    ctx.fillStyle = '#17272a'; ctx.fillRect(x - 18, y - 109, 36, 20); ctx.fillRect(x - 12, y - 121, 24, 14);
    ctx.fillStyle = '#849687'; ctx.fillRect(x - 7, y - 130, 14, 14); ctx.fillStyle = '#c4e79a'; ctx.fillRect(x - 5, y - 128, 10, 4);
    ctx.fillStyle = '#9bff85'; ctx.fillRect(x - 2, y - 126, 4, 1);
    ctx.fillStyle = '#45634c'; ctx.fillRect(x - 18, y - 67, 36, 3); ctx.fillStyle = '#ceff7e'; ctx.fillRect(x - 6, y - 62, 12, 4);
    ctx.fillStyle = '#0d161a'; ctx.fillRect(x - 22, y - 39, 44, 37); ctx.fillStyle = '#354642'; ctx.fillRect(x - 15, y - 32, 30, 25);
    ctx.fillStyle = '#839386'; ctx.fillRect(x - 5, y - 27, 10, 4); ctx.fillStyle = '#16201e'; ctx.fillRect(x - 3, y - 23, 6, 14);
    // pixelated muzzle flash
    if (player.muzzle > 0) { const flick = Math.random() > .3; ctx.fillStyle = '#fff2a1'; ctx.fillRect(x - 11, y - 149, 22, 17); ctx.fillStyle = '#ffae4d'; ctx.fillRect(x - 18, y - 142, 36, 13); ctx.fillStyle = '#efff9c'; ctx.fillRect(x - 6, y - 160, 12, 23); if (flick) { ctx.fillStyle = '#ffed91'; ctx.fillRect(x - 25, y - 135, 8, 6); ctx.fillRect(x + 17, y - 135, 8, 6); } }
  }
  function drawReticle() {
    // The HTML reticle scales crisply with the viewport; world-space center glow adds depth.
    ctx.fillStyle = 'rgba(195,255,204,.14)'; ctx.fillRect(W / 2 - 1, H / 2 - 1, 2, 2);
  }
  function frame(now) {
    const dt = Math.min(.035, (now - last) / 1000); last = now; update(dt); drawWorld(); requestAnimationFrame(frame);
  }

  $('startButton').addEventListener('click', startGame);
  $('restartButton').addEventListener('click', startGame);
  $('soundButton').addEventListener('click', () => { soundOn = !soundOn; $('soundButton').classList.toggle('muted', !soundOn); $('soundButton').innerHTML = soundOn ? '♫ <span>SES AÇIK</span>' : '♫ <span>SES KAPALI</span>'; if (soundOn) tone(420, .08, 'triangle', .025); });
  document.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
    if (e.code === 'KeyR') reload();
    if (e.code === 'Enter' && !started) startGame();
    if (e.code === 'Escape' && running && !pointerLocked) { /* continue with keyboard/mouse */ }
  });
  document.addEventListener('keyup', e => { keys[e.code] = false; });
  document.addEventListener('pointerlockchange', () => { pointerLocked = document.pointerLockElement === canvas; });
  document.addEventListener('mousemove', e => { if (running && pointerLocked) player.angle += e.movementX * .0024; });
  canvas.addEventListener('mousedown', e => { if (e.button !== 0 || !running) return; fireHeld = true; if (!pointerLocked && window.innerWidth > 700 && canvas.requestPointerLock) canvas.requestPointerLock(); else shoot(); });
  window.addEventListener('mouseup', e => { if (e.button === 0) fireHeld = false; });
