  function releaseJoy() { joyActive = false; joyOrigin = null; joyVector = { x: 0, y: 0 }; ui.knob.style.left = '50%'; ui.knob.style.top = '50%'; }
  ui.joy.addEventListener('pointerup', releaseJoy); ui.joy.addEventListener('pointercancel', releaseJoy);
  const fireButton = $('mobileFire');
  fireButton.addEventListener('pointerdown', e => { e.preventDefault(); fireHeld = true; shoot(); });
  fireButton.addEventListener('pointerup', () => { fireHeld = false; }); fireButton.addEventListener('pointercancel', () => { fireHeld = false; }); fireButton.addEventListener('pointerleave', () => { fireHeld = false; });
  $('mobileReload').addEventListener('pointerdown', e => { e.preventDefault(); reload(); });
  window.addEventListener('blur', () => { keys = Object.create(null); fireHeld = false; releaseJoy(); });
  document.addEventListener('contextmenu', e => e.preventDefault());
  updateHud(); requestAnimationFrame(frame);
})();

