(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false}),W=480,H=270,FOV=Math.PI/3;
canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false;
const map=['################','#......#.......#','#.##...#..##...#','#......#.......#','#..............#','#..##......##..#','#..#..........##','#..#..##.......#','#.....##.......#','##............##','#......##......#','#..............#','#..##......##..#','#..............#','#..............#','################'];
const $=id=>document.getElementById(id),ui={start:$('startOverlay'),end:$('endOverlay'),mission:$('missionState'),health:$('healthFill'),healthText:$('healthText'),armor:$('armorFill'),armorText:$('armorText'),ammo:$('ammoText'),reserve:$('reserveText'),wave:$('waveText'),enemies:$('enemyText'),score:$('finalScore'),endTitle:$('endTitle'),endCopy:$('endCopy'),reload:$('reloadNote'),crosshair:$('crosshair'),hit:$('hitMarker'),flash:$('damageFlash'),joy:$('joystick'),knob:$('joyKnob')};
const player={x:2.5,y:2.5,angle:.15,health:100,armor:50,ammo:24,reserve:120,score:0,wave:0,kills:0,bob:0,hurt:0,recoil:0,muzzle:0,reloading:0,fireCooldown:0,alive:true};
let enemies=[],particles=[],running=false,started=false,last=performance.now(),keys=Object.create(null),pointerLocked=false,fireHeld=false,soundOn=true,audio=null,joyActive=false,joyOrigin=null,joyVector={x:0,y:0},lastTouchX=null;
const depthBuffer=new Float32Array(W),random=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),normAngle=a=>{while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a;};
function isWall(x,y){const mx=Math.floor(x),my=Math.floor(y);return !map[my]||map[my][mx]!=='.';}
function tone(freq,duration,type='square',volume=.035){if(!soundOn)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(45,freq*.38),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(_){}}
function updateHud(){ui.health.style.width=`${player.health}%`;ui.healthText.textContent=player.health;ui.armor.style.width=`${player.armor*2}%`;ui.armorText.textContent=player.armor;ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;ui.wave.textContent=String(player.wave).padStart(2,'0');ui.enemies.textContent=enemies.filter(e=>!e.dead).length;}
function spawnWave(){player.wave++;const count=3+player.wave*2;for(let i=0;i<count;i++){let x,y,tries=0;do{x=random(3,13);y=random(2,13);tries++;}while((isWall(x,y)||Math.hypot(x-player.x,y-player.y)<4||enemies.some(e=>Math.hypot(e.x-x,e.y-y)<1.4))&&tries<150);if(tries<150){const heavy=player.wave>=3&&i%4===0;enemies.push({x,y,hp:heavy?3:2,maxHp:heavy?3:2,speed:random(.52,.78)+player.wave*.035,attack:random(.6,1.4),phase:random(0,6),hit:0,type:heavy?'heavy':'scout',dead:false});}}updateHud();}
function startGame(){if(started&&running)return;started=running=player.alive=true;Object.assign(player,{x:2.5,y:2.5,angle:.15,health:100,armor:50,ammo:24,reserve:120,score:0,wave:0,kills:0,reloading:0,fireCooldown:0});enemies=[];particles=[];ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.mission.textContent='TEMİZLE';if(canvas.requestPointerLock&&innerWidth>700)canvas.requestPointerLock();spawnWave();updateHud();}
function finishGame(win){running=false;player.alive=false;if(document.pointerLockElement)document.exitPointerLock();ui.endTitle.textContent=win?'GÖREV TAMAMLANDI':'SİNYAL KESİLDİ';ui.endCopy.textContent=win?'Sektör temizlendi. Şimdilik.':`Dalga ${String(player.wave).padStart(2,'0')}’de düştün. Makineler hâlâ geliyor.`;ui.score.textContent=String(player.score).padStart(4,'0');ui.end.classList.remove('hidden');ui.mission.textContent=win?'TAMAMLANDI':'BAĞLANTI KOPTU';}
function reload(){if(!running||player.reloading||player.ammo>=24||player.reserve<=0)return;player.reloading=1.2;ui.reload.textContent='ŞARJÖR DEĞİŞTİRİLİYOR';ui.reload.classList.add('active');tone(240,.08,'triangle',.025);}
function hasLine(x1,y1,x2,y2){const d=Math.hypot(x2-x1,y2-y1),steps=Math.ceil(d*10);for(let i=1;i<steps;i++){const t=i/steps;if(isWall(x1+(x2-x1)*t,y1+(y2-y1)*t))return false;}return true;}
function shoot(){if(!running||player.reloading||player.fireCooldown>0)return;if(player.ammo<=0){tone(100,.05,'square',.018);reload();return;}player.ammo--;player.fireCooldown=.19;player.recoil=1;player.muzzle=.085;tone(115,.085,'sawtooth',.045);tone(290,.045,'square',.018);let target=null,nearest=1.25;for(const e of enemies){if(e.dead)continue;const dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),a=Math.abs(normAngle(Math.atan2(dy,dx)-player.angle));if(a<.13+.018/dist&&dist<nearest&&hasLine(player.x,player.y,e.x,e.y)){nearest=dist;target=e;}}if(target){target.hp--;target.hit=.12;player.score+=10;ui.crosshair.classList.add('hit');ui.hit.classList.add('show');setTimeout(()=>{ui.crosshair.classList.remove('hit');ui.hit.classList.remove('show');},100);for(let i=0;i<7;i++)particles.push({x:target.x,y:target.y,z:random(.35,1.7),life:random(.12,.32),color:i%2?'#f5e681':'#ff7664',vx:random(-1,1),vy:random(-1,1)});if(target.hp<=0){target.dead=true;player.kills++;player.score+=target.type==='heavy'?100:75;tone(480,.12,'triangle',.035);}}if(player.ammo===0&&player.reserve>0)setTimeout(reload,240);updateHud();}
function takeDamage(amount){const absorbed=Math.min(player.armor,Math.ceil(amount*.65));player.armor-=absorbed;player.health=Math.max(0,player.health-(amount-absorbed));ui.flash.classList.add('show');setTimeout(()=>ui.flash.classList.remove('show'),130);tone(85,.13,'sawtooth',.04);updateHud();if(player.health<=0)finishGame(false);}

